#define LCGF_STATIC_ASSERT _Static_assert
#endif

/* The layout of every type below the library reads: compare with lcgf_layout(). */
#define LCGF_LAYOUT 0x2f1586c6u
#define LCGF_CONTEXT_ALIGN 64
#define LCGF_NO_WIDGET 0xffffffffu
/* The bit of lcgf_view.status set when the stack overflowed. */
#define LCGF_DEPTH_BIT 4

/* What lcgf_context_init and the tables' calls return. */
enum lcgf_status {
    LCGF_OK = 0,
    LCGF_NOT_TABLES = 1,
    LCGF_VERSION = 2,
    LCGF_LAYOUT_HASH = 3,
    LCGF_TRUNCATED = 4,
    LCGF_BUFFER_TOO_SMALL = 5,
    LCGF_UNALIGNED = 6,
};

/* Held by value; only the library reads it. */
typedef struct lcgf_frame {
    void *p_[2];
} lcgf_frame;

typedef struct lcgf_context lcgf_context;
typedef struct lcgf_canvas lcgf_canvas;

