/* Bits, from bit 0: hovered held pressed released clicked focused. */
typedef uint8_t lcgf_response;

/// Bytes a context of `limits` needs, its own included: the buffer `lcgf_context_init` takes.
size_t lcgf_context_required_bytes(const lcgf_limits *limits);
/// Places a context of `limits` at the start of `buf` (LCGF_CONTEXT_ALIGN-aligned): `buf` is
/// then an `lcgf_context *`. Returns an `lcgf_status`.
int lcgf_context_init(void *buf, size_t len, const lcgf_limits *limits);
/// Whether `in` needs a frame: 0 when nothing would change, so the host can sleep.
int lcgf_context_needs_frame(lcgf_context *ctx, const lcgf_input *in);
/// Starts a frame on `in`, which the context copies: `frame` is valid until `lcgf_frame_end`.
void lcgf_context_begin(lcgf_context *ctx, const lcgf_input *in, lcgf_frame *frame_out);
/// Lets frames make canvas nodes (`lcgf_frame_canvas`), in `buf`: `lcgf_context_canvas_bytes`
/// of the caller's memory, pointer-aligned, alive as long as the context.
int lcgf_context_enable_canvas(lcgf_context *ctx, void *buf, size_t len);
/// Bytes `lcgf_context_enable_canvas` needs for `limits`.
size_t lcgf_context_canvas_bytes(const lcgf_limits *limits);
/// Starts a node. Everything created until the matching `close` is its child.
uint32_t lcgf_frame_open(lcgf_frame *f, uint32_t id, const lcgf_style *style);
void lcgf_frame_close(lcgf_frame *f);
/// A node with no children. Same as `open` then `close`.
uint32_t lcgf_frame_leaf(lcgf_frame *f, uint32_t id, const lcgf_style *style);
/// `open` from a style already turned into its row (`Template.from`; a `*const Template`
/// or a C `*const FlatRow`): the row is pushed as it is. What C++ and Rust call, having made the row themselves (src/abi/runtime.zig).
uint32_t lcgf_frame_open_row(lcgf_frame *f, uint32_t id, const lcgf_row *row);
/// `leaf` from a row (`openRow`).
uint32_t lcgf_frame_leaf_row(lcgf_frame *f, uint32_t id, const lcgf_row *row);
/// A text leaf. The bytes are copied, so `str` may be a temporary.
uint32_t lcgf_frame_text(lcgf_frame *f, const char *str, size_t str_len, const lcgf_text_style *ts);
/// `text` with full control over the leaf (padding, sizing, background).
uint32_t lcgf_frame_text_styled(lcgf_frame *f, const char *str, size_t str_len, const lcgf_text_style *ts, const lcgf_style *style);
/// The free end of the frame's strings, to write text into before `textWritten`: how a
/// caller with its own formatter (C++'s `std::format_to_n`, Rust's `fmt::Write`) puts
/// formatted text in the frame without a buffer of its own.
char *lcgf_frame_room(lcgf_frame *f, size_t *len);
/// A text leaf over the `n` bytes just written at `room()`, as `text` would push them; `n`
/// past the room is cut to it, and reported (`Status.strings`).
uint32_t lcgf_frame_text_written(lcgf_frame *f, size_t n, const lcgf_text_style *ts);
/// Reserves a rect that the caller draws itself. It comes back in the draw list as
/// `Cmd.custom`, in paint order, with `data` attached.
uint32_t lcgf_frame_custom(lcgf_frame *f, uint32_t id, const lcgf_style *style, uint64_t data);
/// `custom` from a row (`openRow`).
uint32_t lcgf_frame_custom_row(lcgf_frame *f, uint32_t id, const lcgf_row *row, uint64_t data);
/// A node that draws `o.ranges` of `shapes` under `o.camera` with `o.palette`: a `canvas`
/// command in paint order, clipped to the node. Needs `Context.enableCanvas`. It is a
/// custom row, so it takes a `Limits.customs` row, orders, layers and damages like a
/// custom node; its damage covers the camera, the palette, the ranges, the overrides and
/// `shapes.revision`, so a pan, a recolour or an edit redraws it; not the batch's address, so
/// a batch moved in memory does not redraw (bump `revision` when a node switches to another
/// batch at the same revision). An overlay is a second
/// canvas node over it (a float) or more ranges. Everything passed is the caller's and
/// must outlive the frame's drawing, and a subtree `reuse` keeps draws it again as it was.
uint32_t lcgf_frame_canvas(lcgf_frame *f, uint32_t id, const lcgf_style *style, const lcgf_canvas *shapes, const lcgf_canvas_options *options);
/// A value that eases toward `target` across frames on a spring keyed by `id`. Returns this
/// frame's position (`target` on first use). Keeps the host awake (`Output.wake` 0,
/// `needsFrame` true) until it lands; a spring not asked for in a frame is dropped.
///
/// `target` is an f32 (or a number literal), or anything made of numbers: a `Color`, a
/// `Rect`, `[2]f32`, a vector or a struct of them (src/anim/values.zig). Each component
/// moves on its own spring, keyed `id.with(k)` for the k-th; an f32 is keyed `id` itself.
/// Exhaustion returns target immediately and reports Output.status.anims.
float lcgf_frame_animate(lcgf_frame *f, uint32_t id, float target, const lcgf_spring *spring);
/// A value that moves to `target` over `seconds` along `ease`, keyed by `id`: when the
/// target changes, a new leg starts from the current value. Returns this frame's value
/// (`target` on first use). Keeps the host awake until it lands; a tween not asked for in
/// a frame is dropped. `target` is what `animate` takes, keyed the same way.
/// Exhaustion returns target immediately and reports Output.status.tweens.
float lcgf_frame_tween(lcgf_frame *f, uint32_t id, float target, float seconds, uint32_t ease);
/// Lays the frame out and paints it with the context's font: `out` holds the draw list,
/// valid until the next frame begins.
void lcgf_frame_end(lcgf_frame *f, lcgf_ui_output *out);
/// Where this frame's rows are, for the bindings' inline push (`lcgf_view`): valid until
/// `lcgf_frame_end`.
void lcgf_frame_view(lcgf_frame *f, lcgf_view *out);
uint32_t lcgf_label(lcgf_frame *f, const lcgf_theme *th, const char *str, size_t str_len);
lcgf_response lcgf_button(lcgf_frame *f, const lcgf_theme *th, uint32_t id, const char *str, size_t str_len);
lcgf_response lcgf_checkbox(lcgf_frame *f, const lcgf_theme *th, uint32_t id, bool *value, const char *str, size_t str_len);
lcgf_response lcgf_slider(lcgf_frame *f, const lcgf_theme *th, uint32_t id, float *value, float lo, float hi);
void lcgf_label_text(const lcgf_theme *th, lcgf_text_style *out);
/// An animated number as an integer of the range [lo, hi]: rounded half away from zero, clamped
/// in f64 (where the ends of every type up to 32 bits are exact: an f32 of maxInt(u32) is 2^32),
/// NaN to 0. What `build` does for an integer, and what the C++ and Rust bindings call.
int64_t lcgf_values_int_of(float x, int64_t lo, int64_t hi);
/// The row the tree stores for `style` (`Template.from`): what the _row calls push as it is.
void lcgf_template_from(const lcgf_style *style, lcgf_row *out);
/// `Style`'s defaults.
void lcgf_style_default(lcgf_style *out);
/// The reference widgets' default theme.
void lcgf_theme_default(lcgf_theme *out);
/// The layout this library reads (`LCGF_LAYOUT`): compare before making a context.
uint32_t lcgf_layout(void);

